package com.opspilot.incident.api;
import com.opspilot.incident.infrastructure.persistence.IncidentFacade; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.net.URI; import java.util.UUID; import org.springframework.http.*; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/api/v1/alerts") public class AlertController { private final IncidentFacade facade; public AlertController(IncidentFacade f){facade=f;} @PostMapping("/manual") public ResponseEntity<AlertResponse> create(@Valid @RequestBody ManualAlertRequest r){AlertResponse a=facade.create(r);return ResponseEntity.created(URI.create("/api/v1/alerts/"+a.id())).body(a);}@GetMapping public PageResponse<AlertResponse> list(@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size){return facade.alerts(page,size);}@GetMapping("/{id}") public AlertResponse get(@PathVariable UUID id){return facade.alert(id);} }
